const body = $input.first().json;

// Formspree posila data jako flat object
const jmeno   = body.jmeno || body.name || '';
const email   = body.email || '';
const kava    = body.kava  || '';
const pocet   = parseInt(body.pocet) || 1;
const doprava = body.doprava || 'zasilkovna';
const vydejna = body.vydejna || '';
const adresa  = body.adresa || '';
const telefon = body.telefon || '';
const poznamka = body.poznamka || '';

// Ceny
const ceny = { etiopie: 340, costarica: 320, oba: 660 };
const cenaKavy = ceny[kava] || 0;

// Doprava
let cenahDopravy = 0;
if (pocet < 2 && kava !== 'oba') {
  cenahDopravy = doprava === 'zasilkovna' ? 60 : 89;
}

const celkem = cenaKavy * pocet + cenahDopravy;
const naUkrajinu = 100 * pocet;

// Nazev produktu
const nazvy = { etiopie: 'Ethiopia Single Origin', costarica: 'Costa Rica Single Origin', oba: 'Ethiopia + Costa Rica Bundle' };
const nazevProduktu = nazvy[kava] || kava;

return [{
  json: {
    jmeno, email, kava, pocet, doprava, vydejna, adresa, telefon, poznamka,
    celkem, cenahDopravy, naUkrajinu, nazevProduktu,
    orderDate: new Date().toLocaleDateString('cs-CZ'),
    orderTime: new Date().toLocaleTimeString('cs-CZ')
  }
}];

